lambdared[k___] := lambdared[k] = Module[{lk, t, left, right, i, j, n}, 
      If[admissibleQ[k], lambda[k], lk = {k}; t = 1; 
        While[lk[[t + 1]] <= 2*lk[[t]], t++]; 
        left = lambda @@ lk[[Range[t - 1]]]; 
        right = lambdared @@ lk[[Range[t + 2, Length[lk]]]]; i = lk[[t]]; 
        n = lk[[t + 1]] - 2*i - 1; PolynomialMod[
         Sum[bc[n - 1 - j, j]*o[left, lambdared[i + n - j, 2*i + 1 + j], 
            right], {j, 0, Floor[(n - 1)/2]}], 2]]]
 
k = 2
 
admissibleQ[i___] := And @@ Not /@ Negative /@ (2*{Infinity, i} - {i, 0})
 
